// jitcache-host: bun
// jitcache-runs: Producer; Consumer
// jitcache-runs: Producer; Consumer

// A UCB holds no line and no context records one, so a body imports under any first line of its source. One text holds a
// class with instance fields, a static block and a nested class, nine bodies in all: the program; StartLineOuter's
// default constructor, instance field initializer, static initializer and method; and, generated by that static
// initializer, which evaluates the static fields and the static block, the static block's own function
// (StaticBlockFunctionCallNode calls it), the nested class's default constructor, instance field initializer and
// innerMethod. The program's loop runs 1,000 times: the LLInt counts one point per iteration and compiles the program for
// the baseline at 500 (thresholdForJITAfterWarmUp), so the Producer captures the program too. Each Producer runs the
// text through vm.Script under lineOffset 0; each Consumer runs it under the lineOffset its sequence index picks, 0 then
// 10, and each of the nine bodies imports under both (statistics). The twins pass at every import, and the stack traces
// of errors thrown in a field initializer, in the static block and in the nested class's method equal the JITCache-off
// run in both Consumers.
//
// The Producer and the Consumer of a sequence run with the same options, so the runner compares both with one Off run,
// which follows the Consumer path, as every Off run does, and so prints the traces under the Consumer's lineOffset.
// The Producer prints those traces too: after its capture it throws from the same text under its Consumer's lineOffset,
// where the CodeCache serves it the UCB generated under 0, whose code reports the lines of the source it runs under.
//
// The text names its fields with identifiers the VM makes when it is created (CommonIdentifiers: value, count, target
// and index), so that the runner's leak check, which fails a leak the Off run does not report, never sees them. The
// twin check parses each imported field initializer again, which leaks its field names as the native parse does;
// inside the imported program the decode would be the first to allocate any other name, so the leak would show a stack
// no oracle run reports.
const vm = require("node:vm");
const { context } = require("./resources/ucb-bun.js");

const t = context();
const consumerLineOffset = t.sequence === 1 ? 10 : 0;

// What the text calls back into; `throwFrom` names the place an evaluation throws from, at its first round.
let throwFrom = null;
globalThis.startLineValue = (where, round) => {
    if (where === throwFrom)
        throw new Error(`thrown from the ${where}`);
    return round;
};
// The Producer runs startLineValue hot, so a Consumer imports it at its first call, which happens here, before the
// statistics window, so that the window counts the text's bodies alone.
startLineValue("warm-up", 0);

// The text declares nothing at its top level, so evaluating it again redeclares nothing.
const text = `
{
    let startLineTotal = 0;
    for (let round = 0; round < 1000; ++round) {
        class StartLineOuter {
            value = startLineValue("field initializer", round);
            static count = 7;
            static {
                startLineValue("static block", round);
            }
            static target = class {
                index = round * 2;
                innerMethod() { return this.index + startLineValue("nested class", round); }
            };
            method(x) { return this.value + x; }
        }
        const outer = new StartLineOuter();
        startLineTotal += outer.method(round) + new StartLineOuter.target().innerMethod();
    }
    startLineTotal;
}
`;

function evaluate(source, lineOffset)
{
    return new vm.Script(source, { filename: "start-line-text.js", lineOffset }).runInThisContext();
}

const before = t.statistics();
const total = evaluate(text, t.role === "Producer" ? 0 : consumerLineOffset);
const after = t.statistics();
if (t.role === "Consumer")
    t.expect(`the text under lineOffset ${consumerLineOffset}`, t.delta(before, after), { imports: 9, "misses.Context": 0, "misses.Holder": 0 });
console.log(`total ${total}`);

for (const where of ["field initializer", "static block", "nested class"]) {
    throwFrom = where;
    try {
        evaluate(text, consumerLineOffset);
        console.log(`nothing was thrown from the ${where}`);
    } catch (error) {
        console.log(error.stack);
    }
}
throwFrom = null;
t.finish();
